                                                   const primary = next.includes(editCourseDraft.primarySubjectId) ? editCourseDraft.primarySubjectId : (next[0] || '');
                                                   setEditCourseDraft({ ...editCourseDraft, subjectIds: next, primarySubjectId: primary });
